      "content": "/**
 * The WorkbenchService implementation: one registry per extension surface
 * (activity items / panels / editor views / status items / commands) plus
 * layout read/write proxying to the layout store. One instance per client
 * activation; published as `ctx.workbench` in the client apply().
 *
 * Design notes (Phase 1):
 * - Synchronous snapshot registries (Map + listener set) so React reads them
 *   through useSyncExternalStore without tearing.
 * - Every register* returns a disposer; consumers wrap it in ctx.effect()
 *   so fiber disposal (HMR / disable) unregisters cleanly.
 * - Duplicate ids throw, like the sidebar registry (package-prefix ids
 *   recommended: 'files', 'my-plugin:db').
 */
import type {
  ActivityBarItemDefinition,
  CloseRequest,
  CommandDefinition,
  EditorOpenSeed,
  FloatingWindow,
  OpenPathOptions,
  StatusBarItemDefinition,
  ViewDefinition,
  WorkbenchLayout,
  WorkbenchService,
} from './contract.ts'
import { FLOATING_HEAD_HEIGHT } from './ui-constants.ts'
import type { LayoutStore } from './layout.ts'
import { DOCK_AUTO_HIDE_SETTING, DOCK_BASE_ICON, DOCK_BASE_PLUGIN_ID, DOCK_HOVER_SCALE_SETTING, DOCK_NEAR_SCALE_SETTING, DOCK_POSITION_SETTING, DOCK_RESERVE_SETTING, DOCK_SETTINGS_ACTIVITY_ID, DOCK_SETTINGS_ACTIVITY_ORDER, HIDDEN_PLUGINS_SETTING, HIDDEN_PLUGINS_SETTING_ID } from './settings.ts'
import { getDockLocale, settingsLabels } from './internal/localization.ts'
import type { PluginDefinition } from './contract.ts'
import type { SettingDefinition, SettingsStore } from './settings.ts'

/**
 * Merge a seed patch onto an existing seed. `patch.meta` is shallow-merged
 * into the current meta when both are plain objects (an editor writes its
 * dirty flag as `{ meta: { dirty: true } }` without knowing the rest of the
 * meta); every other patch field replaces its seed counterpart wholesale.
 */
function mergeSeed(seed: EditorOpenSeed | undefined, patch: Partial<EditorOpenSeed>): EditorOpenSeed {
  const base = seed ?? {}
  const meta = patch.meta === undefined
    ? base.meta
    : (typeof patch.meta === 'object' && patch.meta !== null
        && typeof base.meta === 'object' && base.meta !== null
      ? { ...(base.meta as Record<string, unknown>), ...(patch.meta as Record<string, unknown>) }
      : patch.meta)
  return { ...base, ...patch, meta }
}

// ── Floating-window geometry memory ───────────────────────────────────────
// The last position/size of a floating window is remembered per view id in
// the browser (localStorage), so reopening a view restores where the user
// left it. The layout's own floatingWindows persistence covers the *open*
// lifetime; this key survives closing, so the *next* open lands on the
// remembered geometry instead of the default.

/** localStorage key for one view's remembered floating geometry. */
const FLOATING_GEO_KEY = (viewId: string): string => `dock:floating-geometry:${viewId}`

/** Read the remembered geometry for a view, or undefined when none is saved. */
function rememberFloatingGeometry(viewId: string): { x: number; y: number; width: number; height: number } | undefined {
  if (typeof window === 'undefined' || window.localStorage === undefined) return undefined
  try {
    const raw = window.localStorage.getItem(FLOATING_GEO_KEY(viewId))
    if (raw === null) return undefined
    const parsed = JSON.parse(raw) as { x?: unknown; y?: unknown; width?: unknown; height?: unknown }
    if (
      typeof parsed.x === 'number' && typeof parsed.y === 'number'
      && typeof parsed.width === 'number' && typeof parsed.height === 'number'
      && Number.isFinite(parsed.x) && Number.isFinite(parsed.y)
      && parsed.width >= 240 && parsed.height >= 160
    ) {
      return { x: parsed.x, y: parsed.y, width: parsed.width, height: parsed.height }
    }
  } catch { /* corrupt entry: ignore */ }
  return undefined
}

/** Remember a view's floating geometry in the browser. */
function saveFloatingGeometry(
  viewId: string,
  geometry: { x: number; y: number; width: number; height: number },
): void {
  if (typeof window === 'undefined' || window.localStorage === undefined) return
  try {
    window.localStorage.setItem(FLOATING_GEO_KEY(viewId), JSON.stringify(geometry))
  } catch { /* storage unavailable/full: degrade silently */ }
}

/**
 * Clamp a floating-window rect so its title bar (the top
 * `FLOATING_HEAD_HEIGHT` strip, spanning the window width) stays fully
 * inside the viewport. The body may extend past the bottom edge, but the
 * head — with the move grip and the close button — is always reachable, so
 * a window can never be dragged into an uncontrollable position. No-op
 * outside a browser (no viewport to measure).
 */
function clampRect(x: number, y: number, width: number, height: number): { x: number; y: number } {
  if (typeof window === 'undefined') return { x, y }
  return {
    x: Math.min(Math.max(0, x), Math.max(0, window.innerWidth - width)),
    y: Math.min(Math.max(0, y), Math.max(0, window.innerHeight - FLOATING_HEAD_HEIGHT)),
  }
}

export function createWorkbenchService(store: LayoutStore, settings: SettingsStore): WorkbenchService {
  const plugins = new Map<string, PluginDefinition>()
  const pluginListeners = new Set<() => void>()
  const activityItems = new Map<string, ActivityBarItemDefinition>()
  const panels = new Map<string, ViewDefinition & { region: 'sideBar' }>()
  const editorViews = new Map<string, ViewDefinition>()
  const statusItems = new Map<string, StatusBarItemDefinition>()
  const commands = new Map<string, CommandDefinition>()
  const listeners = new Set<() => void>()

  const notify = (): void => {
    for (const listener of [...listeners]) listener()
  }
  const notifyPlugins = (): void => {
    notify()
    for (const listener of [...pluginListeners]) listener()
  }
  const registerPlugin = (def: PluginDefinition): (() => void) => {
    if (plugins.has(def.id)) throw new Error(`[dock] plugin "${def.id}" already registered`)
    plugins.set(def.id, def)
    notifyPlugins()
    return () => { if (plugins.get(def.id) === def) { plugins.delete(def.id); notifyPlugins() } }
  }
  const onDidChangePlugins = (listener: () => void): (() => void) => {
    pluginListeners.add(listener)
    return () => { pluginListeners.delete(listener) }
  }

  // The workbench itself is a first-class entry in its own registry. Keep the
  // disposer in the service so client-fiber disposal cannot orphan this row.
  const disposeDockPlugin = registerPlugin({
    id: DOCK_BASE_PLUGIN_ID,
    title: 'Dock',
    description: 'Workbench dock and settings',
    icon: DOCK_BASE_ICON,
    hasEntry: true,
    order: 0,
  })

  const subscribe = (listener: () => void): (() => void) => {
    listeners.add(listener)
    return () => { listeners.delete(listener) }
  }

  const registerActivityBarItem = (def: ActivityBarItemDefinition): (() => void) => {
    if (activityItems.has(def.id)) throw new Error(`[dock] activity item "${def.id}" already registered`)
    activityItems.set(def.id, def)
    notify()
    return () => { if (activityItems.get(def.id) === def) { activityItems.delete(def.id); notify() } }
  }

  // Dock's own entry in its own bar: activating it opens the settings window
  // (the shell intercepts this id) instead of revealing a pane, which is why
  // `paneId` is empty and the settings card offers no "Open" for it. Living in
  // the activity registry is what makes the plugin visibility switch real —
  // the "Dock" card hides exactly this entry — and it keeps the icon
  // draggable/orderable alongside the feature entries. It sorts last so the
  // dock's own control never displaces a feature icon.
  const disposeDockSettingsEntry = registerActivityBarItem({
    id: DOCK_SETTINGS_ACTIVITY_ID,
    pluginId: DOCK_BASE_PLUGIN_ID,
    title: settingsLabels(getDockLocale()).dockSettings,
    icon: DOCK_BASE_ICON,
    order: DOCK_SETTINGS_ACTIVITY_ORDER,
    paneId: '',
  })

  const registerPanel = (def: ViewDefinition & { region: 'sideBar' }): (() => void) => {
    if (panels.has(def.id)) throw new Error(`[dock] panel "${def.id}" already registered`)
    panels.set(def.id, def)
    notify()
    return () => { if (panels.get(def.id) === def) { panels.delete(def.id); notify() } }
  }

  const registerEditorView = (def: ViewDefinition): (() => void) => {
    if (editorViews.has(def.id)) throw new Error(`[dock] editor view "${def.id}" already registered`)
    editorViews.set(def.id, def)
    notify()
    return () => { if (editorViews.get(def.id) === def) { editorViews.delete(def.id); notify() } }
  }

  const registerStatusBarItem = (def: StatusBarItemDefinition): (() => void) => {
    if (statusItems.has(def.id)) throw new Error(`[dock] status item "${def.id}" already registered`)
    statusItems.set(def.id, def)
    notify()
    return () => { if (statusItems.get(def.id) === def) { statusItems.delete(def.id); notify() } }
  }

  const registerCommand = (def: CommandDefinition): (() => void) => {
    if (commands.has(def.id)) throw new Error(`[dock] command "${def.id}" already registered`)
    commands.set(def.id, def)
    notify()
    return () => { if (commands.get(def.id) === def) { commands.delete(def.id); notify() } }
  }

  const executeCommand = async (id: string, ...args: unknown[]): Promise<unknown> => {
    const command = commands.get(id)
    if (command === undefined) {
      console.warn(`[dock] unknown command "${id}"`)
      return undefined
    }
    return command.run(...args)
  }

  // ── View instances: one open view = one instance id, hosted either in the
  //    editor-area tabs or in a floating window. ──
  let uidCounter = 0
  const uid = (): string => `vi:${++uidCounter}`

  /** Outcome of a view's `beforeClose` gate: synchronously allowed or
   *  cancelled, or pending while an async hook runs (the caller decides what
   *  happens on resolution). */
  type BeforeCloseResult =
    | { kind: 'allowed' }
    | { kind: 'cancelled' }
    | { kind: 'pending'; then(onAllow: () => void): void }

  /**
   * Evaluate the instance's view-defined `beforeClose` gate. No hook → the
   * gate is trivially allowed; a synchronous `false` cancels; a synchronous
   * `true`/`undefined` allows; a promise defers the decision to its
   * resolution (any non-`false` value allows). Shared by `closeViewInstance`
   * and `openView` so replacing an instance's content (switching files) is
   * gated exactly like closing it — a dirty editor must confirm before its
   * content is discarded.
   */
  const evaluateBeforeClose = (entry: CloseRequest): BeforeCloseResult => {
    const beforeClose = editorViews.get(entry.viewId)?.beforeClose
    if (beforeClose === undefined) return { kind: 'allowed' }
    const verdict = beforeClose(entry)
    if (typeof verdict === 'object' && verdict !== null && typeof (verdict as Promise<boolean>).then === 'function') {
      return {
        kind: 'pending',
        then(onAllow) {
          void (verdict as Promise<boolean>).then((allow) => { if (allow !== false) onAllow() })
        },
      }
    }
    return verdict === false ? { kind: 'cancelled' } : { kind: 'allowed' }
  }

  const openView = (viewId: string, seed?: EditorOpenSeed, options?: { floating?: boolean }): string => {
    const current = store.getLayout()
    if (options?.floating === true) {
      // One floating instance per view (Phase F1; multi-instance lands later).
      const existingEntry = Object.entries(current.floatingWindows).find(([, win]) => win.viewId === viewId)
      if (existingEntry !== undefined) {
        const [instanceId, win] = existingEntry
        if (seed !== undefined) {
          // Reusing the window replaces the old content: switching files is
          // like closing the old one, so a dirty instance must confirm first
          // (the view's beforeClose gate). A cancelled gate keeps the old
          // seed — no silent discard — and the open resolves to the existing
          // window either way.
          const gate = evaluateBeforeClose(win)
          if (gate.kind === 'cancelled') return instanceId
          if (gate.kind === 'pending') {
            gate.then(() => replaceFloatingSeed(instanceId, seed))
            return instanceId
          }
          replaceFloatingSeed(instanceId, seed)
        }
        return instanceId
      }
      const instanceId = uid()
      const remembered = rememberFloatingGeometry(viewId)
      const width = remembered?.width ?? 520
      const height = remembered?.height ?? 360
      // Clamp the initial placement too: remembered geometry from a larger
      // screen must not open a window with its title bar out of reach.
      const { x, y } = clampRect(remembered?.x ?? 120, remembered?.y ?? 80, width, height)
      store.update({
        floatingWindows: {
          ...current.floatingWindows,
          [instanceId]: {
            instanceId,
            viewId,
            seed,
            x,
            y,
            width,
            height,
          },
        },
      })
      return instanceId
    }
    // Editor-area tab: focus an existing instance of the view, else open one.
    const existing = current.editorTabs.find((tab) => tab.viewId === viewId)
    if (existing !== undefined) {
      if (seed !== undefined) {
        // Same gate as the floating reuse: replacing the tab's seed discards
        // the old content, so a dirty instance must confirm first. A
        // cancelled gate aborts the open without touching the tab.
        const gate = evaluateBeforeClose(existing)
        if (gate.kind === 'cancelled') return existing.instanceId
        if (gate.kind === 'pending') {
          gate.then(() => replaceTabSeed(existing.instanceId, seed))
          return existing.instanceId
        }
        replaceTabSeed(existing.instanceId, seed)
      } else {
        store.update({ activeEditorTab: existing.instanceId })
      }
      return existing.instanceId
    }
    const instanceId = uid()
    store.update({
      editorTabs: [...current.editorTabs, { instanceId, viewId, seed }],
      activeEditorTab: instanceId,
    })
    return instanceId
  }

  /** Replace a floating window's seed. Re-reads the layout so a deferred
   *  (async gate) application is safe; unknown ids are a no-op. */
  const replaceFloatingSeed = (instanceId: string, seed: EditorOpenSeed): void => {
    const current = store.getLayout()
    const win = current.floatingWindows[instanceId]
    if (win === undefined) return
    store.update({ floatingWindows: { ...current.floatingWindows, [instanceId]: { ...win, seed } } })
  }

  /** Replace an editor tab's seed and activate it. Re-reads the layout so a
   *  deferred (async gate) application is safe; unknown ids are a no-op. */
  const replaceTabSeed = (instanceId: string, seed: EditorOpenSeed): void => {
    const current = store.getLayout()
    const tabs = current.editorTabs.map((tab) => tab.instanceId === instanceId ? { ...tab, seed } : tab)
    if (tabs.every((tab, index) => tab === current.editorTabs[index])) return
    store.update({ editorTabs: tabs, activeEditorTab: instanceId })
  }

  /**
   * Close one view instance (tab or floating window). Before touching the
   * layout the instance's view definition is consulted: a registered
   * `beforeClose` hook receives `{ viewId, instanceId, seed }` and may
   * cancel the close by returning `false` (or a promise resolving to
   * `false`). The call is fire-and-forget — with an async hook the layout
   * stays open until the verdict resolves, then the close is performed on
   * approval. Unknown instance ids are a no-op.
   */
  const closeViewInstance = (instanceId: string): void => {
    const current = store.getLayout()
    // Resolve the instance (tab or floating window) and its view definition.
    const tab = current.editorTabs.find((entry) => entry.instanceId === instanceId)
    const win = current.floatingWindows[instanceId]
    const entry = tab ?? win
    if (entry === undefined) return
    const gate = evaluateBeforeClose(entry)
    if (gate.kind === 'cancelled') return
    if (gate.kind === 'pending') { gate.then(() => performClose(instanceId)); return }
    performClose(instanceId)
  }

  const performClose = (instanceId: string): void => {
    const current = store.getLayout()
    const editorTabs = current.editorTabs.filter((tab) => tab.instanceId !== instanceId)
    let activeEditorTab = current.activeEditorTab
    if (activeEditorTab === instanceId) {
      activeEditorTab = editorTabs.length > 0 ? editorTabs[editorTabs.length - 1]!.instanceId : null
    }
    const floatingWindows = { ...current.floatingWindows }
    delete floatingWindows[instanceId]
    store.update({ editorTabs, activeEditorTab, floatingWindows })
  }

  /**
   * Patch one open instance's seed in place (editor tab or floating window;
   * unknown ids are a no-op). `patch.meta` is shallow-merged into the
   * instance's current meta when both are plain objects; other patch fields
   * replace their seed counterparts wholesale. Persisted with the layout, so
   * instance-level state (e.g. an editor's dirty flag) survives reloads.
   */
  const updateViewSeed = (instanceId: string, patch: Partial<EditorOpenSeed>): void => {
    const current = store.getLayout()
    const tab = current.editorTabs.find((entry) => entry.instanceId === instanceId)
    if (tab !== undefined) {
      store.update({
        editorTabs: current.editorTabs.map((entry) => (
          entry.instanceId === instanceId ? { ...entry, seed: mergeSeed(entry.seed, patch) } : entry
        )),
      })
      return
    }
    const win = current.floatingWindows[instanceId]
    if (win !== undefined) {
      store.update({
        floatingWindows: { ...current.floatingWindows, [instanceId]: { ...win, seed: mergeSeed(win.seed, patch) } },
      })
    }
  }

  // Open-path routing: the file-domain host (dock-files) registers a handler
  // through registerOpenPathHandler; openPath dispatches to it (defaulting to
  // the 'editor' view when no handler exists).
  let openPathHandler: ((path: string, options?: OpenPathOptions) => void) | undefined
  const registerOpenPathHandler = (handler: (path: string, options?: OpenPathOptions) => void): (() => void) => {
    openPathHandler = handler
    return () => { if (openPathHandler === handler) openPathHandler = undefined }
  }
  const openPath = (path: string, options?: OpenPathOptions): void => {
    if (openPathHandler !== undefined) {
      openPathHandler(path, options)
      return
    }
    // No file-domain host: fall back to opening the default file view directly.
    openView(options?.viewId ?? 'editor', { path, title: options?.title })
  }

  const moveFloatingWindow = (instanceId: string, x: number, y: number): void => {
    const current = store.getLayout()
    const win = current.floatingWindows[instanceId]
    if (win === undefined) return
    const clamped = clampRect(x, y, win.width, win.height)
    store.update({ floatingWindows: { ...current.floatingWindows, [instanceId]: { ...win, x: clamped.x, y: clamped.y } } })
    saveFloatingGeometry(win.viewId, { x: clamped.x, y: clamped.y, width: win.width, height: win.height })
  }
  const resizeFloatingWindow = (instanceId: string, x: number, y: number, width: number, height: number): void => {
    const current = store.getLayout()
    const win = current.floatingWindows[instanceId]
    if (win === undefined) return
    const clamped = clampRect(x, y, width, height)
    store.update({
      floatingWindows: { ...current.floatingWindows, [instanceId]: { ...win, x: clamped.x, y: clamped.y, width, height } },
    })
    saveFloatingGeometry(win.viewId, { x: clamped.x, y: clamped.y, width, height })
  }
  /** Pull every open floating window's title bar back into the viewport.
   *  Only touches windows that are actually out of bounds (viewport shrink,
   *  or geometry remembered on a larger screen); drags clamp live already. */
  const clampFloatingWindowsIntoView = (): void => {
    const current = store.getLayout()
    let changed = false
    const floatingWindows: Record<string, FloatingWindow> = {}
    for (const [id, win] of Object.entries(current.floatingWindows)) {
      const clamped = clampRect(win.x, win.y, win.width, win.height)
      if (clamped.x !== win.x || clamped.y !== win.y) {
        floatingWindows[id] = { ...win, x: clamped.x, y: clamped.y }
        changed = true
      } else {
        floatingWindows[id] = win
      }
    }
    if (!changed) return
    store.update({ floatingWindows })
    for (const win of Object.values(floatingWindows)) {
      saveFloatingGeometry(win.viewId, { x: win.x, y: win.y, width: win.width, height: win.height })
    }
  }

  // Dock-owned settings are adapters over the layout store: either surface can
  // be used by settings UI or the context menu without creating a second owner.
  // Keep their registration disposers with the service so the client fiber can
  // tear down this whole adapter when the dock stops.
  const disposeDockPositionSetting = settings.register(DOCK_POSITION_SETTING)
  const disposeDockAutoHideSetting = settings.register(DOCK_AUTO_HIDE_SETTING)
  const disposeDockReserveSetting = settings.register(DOCK_RESERVE_SETTING)
  const disposeDockHoverScaleSetting = settings.register(DOCK_HOVER_SCALE_SETTING)
  const disposeDockNearScaleSetting = settings.register(DOCK_NEAR_SCALE_SETTING)
  const disposeHiddenPluginsSetting = settings.register(HIDDEN_PLUGINS_SETTING)
  const syncLayoutToSettings = (): void => {
    const layout = store.getLayout()
    if (settings.get(DOCK_POSITION_SETTING.id) !== layout.dock) settings.set(DOCK_POSITION_SETTING.id, layout.dock)
    if (settings.get(DOCK_AUTO_HIDE_SETTING.id) !== layout.autoHide) settings.set(DOCK_AUTO_HIDE_SETTING.id, layout.autoHide)
  }
  syncLayoutToSettings()
  // The two magnification factors describe one fisheye: a neighbour can never
  // grow more than the icon under the cursor. Enforcing the invariant here —
  // the owner of these settings — keeps both sliders freely adjustable in
  // their own range without ever producing an inside-out dock. The write is
  // idempotent, so the resulting notification settles immediately.
  const syncMagnification = (): void => {
    const hover = settings.get<number>(DOCK_HOVER_SCALE_SETTING.id)
    const near = settings.get<number>(DOCK_NEAR_SCALE_SETTING.id)
    if (hover === undefined || near === undefined || near <= hover) return
    settings.set(DOCK_NEAR_SCALE_SETTING.id, hover)
  }
  syncMagnification()
  const stopLayoutSync = store.subscribe(syncLayoutToSettings)
  const stopSettingSync = settings.subscribe(() => {
    const dock = settings.get<'left' | 'right' | 'top' | 'bottom'>(DOCK_POSITION_SETTING.id)
    const autoHide = settings.get<'off' | 'edge'>(DOCK_AUTO_HIDE_SETTING.id)
    const patch: Partial<WorkbenchLayout> = {}
    if (dock !== undefined && dock !== store.getLayout().dock) patch.dock = dock
    if (autoHide !== undefined && autoHide !== store.getLayout().autoHide) patch.autoHide = autoHide
    if (Object.keys(patch).length > 0) store.update(patch)
    syncMagnification()
  })
  let disposed = false
  const dispose = (): void => {
    if (disposed) return
    disposed = true
    stopLayoutSync()
    stopSettingSync()
    disposeDockSettingsEntry()
    disposeDockPlugin()
    disposeHiddenPluginsSetting()
    disposeDockNearScaleSetting()
    disposeDockHoverScaleSetting()
    disposeDockReserveSetting()
    disposeDockAutoHideSetting()
    disposeDockPositionSetting()
  }

  return {
    dispose,
    registerPlugin,
    getPlugin: (id) => plugins.get(id),
    getPlugins: () => Array.from(plugins.values()).sort((a, b) => (a.order ?? 100) - (b.order ?? 100)),
    onDidChangePlugins,
    registerActivityBarItem,
    registerPanel,
    registerEditorView,
    registerStatusBarItem,
    registerCommand,
    executeCommand,
    getLayout: () => store.getLayout(),
    updateLayout: (patch: Partial<WorkbenchLayout>) => store.update(patch),
    onDidChangeLayout: (listener: () => void) => store.subscribe(listener),
    openView,
    closeViewInstance,
    updateViewSeed,
    moveFloatingWindow,
    resizeFloatingWindow,
    clampFloatingWindowsIntoView,
    openPath,
    registerOpenPathHandler,
    getPanel: (id) => panels.get(id),
    getEditorView: (id) => editorViews.get(id),
    getActivityItem: (id) => activityItems.get(id),
    getPanels: () => Array.from(panels.values()),
    getEditorViews: () => Array.from(editorViews.values()),
    getActivityItems: () => Array.from(activityItems.values()),
    getStatusItems: () => Array.from(statusItems.values()),
    getCommands: () => Array.from(commands.values()),
    subscribe,
    registerSetting: <T>(definition: SettingDefinition<T>) => settings.register(definition),
    getSettings: (pluginId?: string) => pluginId === undefined
      ? settings.getDefinitions()
      : settings.getDefinitions().filter((definition) => definition.pluginId === pluginId),
    getSetting: <T = unknown>(id: string) => settings.get<T>(id),
    setSetting: <T = unknown>(id: string, value: T) => settings.set(id, value),
    onDidChangeSetting: (listener: () => void) => settings.subscribe(listener),
    getHiddenPluginIds: () => settings.get<string[]>(HIDDEN_PLUGINS_SETTING_ID) ?? [],
    setPluginHidden: (pluginId: string, hidden: boolean) => {
      const current = settings.get<string[]>(HIDDEN_PLUGINS_SETTING_ID) ?? []
      const next = hidden ? [...new Set([...current, pluginId])] : current.filter((id) => id !== pluginId)
      settings.set(HIDDEN_PLUGINS_SETTING_ID, next)
    },
  }
}
